import{_ as s,o as e,c as l,a3 as o,j as t,a}from"./chunks/framework.Cc-oPviL.js";const c=JSON.parse('{"title":"第八章　预测","description":"","frontmatter":{},"headers":[],"relativePath":"timeseries/08.md","filePath":"timeseries/08.md"}'),n={name:"timeseries/08.md"};function d(h,r,i,p,_,g){return e(),l("div",null,[...r[0]||(r[0]=[o('<h1 id="第八章-预测" tabindex="-1">第八章　预测 <a class="header-anchor" href="#第八章-预测" aria-label="Permalink to &quot;第八章　预测&quot;">​</a></h1><p>预测的理论核心是条件期望与误差方差。本章推导 ARMA 的预测公式与区间宽度，并解释为什么含单位根的模型区间会按根号 h 扩张。</p><h2 id="_8-1-最小均方误差预测" tabindex="-1">8.1 最小均方误差预测 <a class="header-anchor" href="#_8-1-最小均方误差预测" aria-label="Permalink to &quot;8.1 最小均方误差预测&quot;">​</a></h2><p>在平方损失下，最优预测是<strong>条件期望</strong>：</p><blockquote><p>ŷ_{T+h} = E(y_{T+h} | F_T)</p></blockquote><p>其中 F_T 是到 T 期为止的全部信息。这就是&quot;最小均方误差预测&quot;（MMSE）。</p><p>严格说，条件期望在<strong>所有</strong>预测函数中最小化 MSE；若限定为线性函数，得到的是<strong>线性投影</strong>，两者只在联合正态下相同。ARMA 框架下的预测公式给出的正是线性投影。</p><p><strong>预测误差</strong>：e_{T+h} = y_{T+h} − ŷ_{T+h}，其条件均值为零（无偏）。</p><h2 id="_8-2-ar-p-的递推预测" tabindex="-1">8.2 AR(p) 的递推预测 <a class="header-anchor" href="#_8-2-ar-p-的递推预测" aria-label="Permalink to &quot;8.2 AR(p) 的递推预测&quot;">​</a></h2>',9),t("blockquote",null,[t("p",{"T−p+2":""},[a("一步：ŷ_{T+1} = c + φ₁y_T + φ₂y_{T−1} + … + φ_py_{T−p+1}"),t("br"),a(" 二步：ŷ_{T+2} = c + φ₁ŷ_{T+1} + φ₂y_T + … + φ_py_")])],-1),o('<p>关键点是：<strong>多步预测时，未知的未来值用其预测值代入</strong>。随着 h 增大，越来越多的真实值被预测值替代，误差逐层累积。</p><p>当 h → ∞ 时，ŷ_{T+h} → μ = c/(1 − Σφᵢ)，即收敛到无条件均值。</p><h2 id="_8-3-ma-q-的预测" tabindex="-1">8.3 MA(q) 的预测 <a class="header-anchor" href="#_8-3-ma-q-的预测" aria-label="Permalink to &quot;8.3 MA(q) 的预测&quot;">​</a></h2><p>MA(q) 的记忆只有 q 期，因此：</p><blockquote><p>当 h ≤ q：ŷ_{T+h} = μ + Σⱼ₌ₕ^q θⱼ ε_{T+h−j}<br> 当 h &gt; q：ŷ_{T+h} = μ</p></blockquote><p>也就是说，<strong>超过 q 步之后，MA 的预测就是均值</strong>。这是 MA 模型&quot;短记忆&quot;的直接体现。</p><h2 id="_8-4-arma-的预测与误差方差" tabindex="-1">8.4 ARMA 的预测与误差方差 <a class="header-anchor" href="#_8-4-arma-的预测与误差方差" aria-label="Permalink to &quot;8.4 ARMA 的预测与误差方差&quot;">​</a></h2><p>用 MA(∞) 表示最方便：</p>',8),t("blockquote",null,[t("p",{"T+h−j":""},"y_{T+h} = μ + Σⱼ₌₀^∞ ψⱼ ε_")],-1),o('<p>其中 j &lt; h 的项含未来冲击（不可知，期望为零），j ≥ h 的项含已知的历史冲击。因此</p><blockquote><p><strong>ŷ_{T+h} = μ + Σⱼ₌ₕ^∞ ψⱼ ε_{T+h−j}</strong></p></blockquote><p>预测误差为</p><blockquote><p><strong>e_h = Σⱼ₌₀^{h−1} ψⱼ ε_{T+h−j}</strong></p></blockquote><p>由于 ε 相互独立、方差 σ²，误差方差为</p><blockquote><p><strong>Var(e_h) = σ² Σⱼ₌₀^{h−1} ψⱼ²</strong></p></blockquote><p>这个公式是全部预测区间理论的基石。三个直接推论：</p><ol><li>h 增大时求和项增多，方差<strong>单调不减</strong>；</li><li>当 h → ∞，方差收敛到 σ² Σⱼ₌₀^∞ ψⱼ²（<strong>无条件方差</strong>），前提是 ψⱼ 平方可和（平稳）；</li><li>若模型含单位根，ψⱼ 不衰减，方差随 h <strong>无界增长</strong>。</li></ol><h2 id="_8-5-预测区间" tabindex="-1">8.5 预测区间 <a class="header-anchor" href="#_8-5-预测区间" aria-label="Permalink to &quot;8.5 预测区间&quot;">​</a></h2><p>在正态假设下，h 步预测的 95% 区间为</p><blockquote><p>ŷ_{T+h} ± 1.96 · σ · √(Σⱼ₌₀^{h−1} ψⱼ²)</p></blockquote><p>★ <strong>区间宽度随 h 如何增长？</strong> 取决于 ψⱼ 的衰减速度：</p><ul><li><strong>平稳 ARMA</strong>：ψⱼ 指数衰减，Σψⱼ² 很快收敛 → 区间宽度很快趋于一个上界。</li><li><strong>ARIMA(0,1,1)</strong>：ψ₀ = 1，ψⱼ = 1 + θ（j ≥ 1），不衰减 → Σψⱼ² = 1 + (h−1)(1+θ)²，<strong>与 h 成正比</strong> → 区间宽度按 <strong>√h</strong> 增长。</li></ul><p>这解释了为什么随机游走类模型的长期预测区间会张得非常大——这是模型性质的必然结果，不是估计不准。</p><p>★ <strong>实际区间通常偏窄</strong>，原因有三：</p><ol><li><strong>忽略参数不确定性</strong>。公式把 φ、θ、σ² 当作已知，实际它们是估计出来的，会带来额外方差。</li><li><strong>假设模型正确</strong>。结构变化、遗漏变量都会让真实误差大于公式值。</li><li><strong>忽略厚尾与异方差</strong>。正态分位数在厚尾分布下偏小。</li></ol><p>实践中可以用 bootstrap（重抽样残差、重新估计、重新预测）得到更接近真实的区间。</p><h2 id="_8-6-长期预测的收敛行为" tabindex="-1">8.6 长期预测的收敛行为 <a class="header-anchor" href="#_8-6-长期预测的收敛行为" aria-label="Permalink to &quot;8.6 长期预测的收敛行为&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>h → ∞ 时预测值</th><th>区间宽度</th></tr></thead><tbody><tr><td>平稳 ARMA（无常数）</td><td>收敛到 0</td><td>收敛到常数</td></tr><tr><td>平稳 ARMA（含常数）</td><td>收敛到 μ = c/(1−Σφ)</td><td>收敛到常数</td></tr><tr><td>ARIMA(p,1,q) 无漂移</td><td>收敛到一条水平线（最后观测值附近）</td><td>按 √h 增长</td></tr><tr><td>ARIMA(p,1,q) 含漂移</td><td>收敛到一条<strong>斜率为 c 的直线</strong></td><td>按 √h 增长</td></tr><tr><td>趋势平稳（退势后建模）</td><td>收敛到趋势线</td><td>收敛到常数</td></tr></tbody></table><p>★ <strong>含漂移 ARIMA 的长期预测是一条直线</strong>，这是很多人看到&quot;预测图后半段变成直线&quot;的原因。这条直线的斜率完全由漂移项决定，所以<strong>漂移项是否可信，直接决定长期预测是否可信</strong>。若漂移不显著而仍被保留，长期预测就会带有一个方向明确但统计上无依据的趋势。</p><h2 id="_8-7-预测失效的三个来源" tabindex="-1">8.7 预测失效的三个来源 <a class="header-anchor" href="#_8-7-预测失效的三个来源" aria-label="Permalink to &quot;8.7 预测失效的三个来源&quot;">​</a></h2><ol><li><strong>模型错误</strong>：真实机制改变（结构突变），模型仍在用旧参数。</li><li><strong>参数不确定性</strong>：参数估计误差在长预测期被放大。</li><li><strong>不可预测的冲击</strong>：新信息本身不可预知，这是预测误差的下界，无法消除。</li></ol><p>★ 三者中，第一类最致命也最常被忽视。<strong>任何模型的预测能力都以&quot;生成机制不变&quot;为前提</strong>，这个前提在长样本上几乎总是不成立。</p><h2 id="_8-8-组合预测" tabindex="-1">8.8 组合预测 <a class="header-anchor" href="#_8-8-组合预测" aria-label="Permalink to &quot;8.8 组合预测&quot;">​</a></h2><p>把多个模型的预测加权平均：</p><blockquote><p>ŷ_combo = Σᵢ wᵢ ŷᵢ</p></blockquote><p>理论与实证都表明，<strong>简单平均（等权）往往优于估计最优权重</strong>。原因是权重估计本身有误差，在样本短时误差可能大于收益。</p><p>组合预测有效的前提是各模型的误差<strong>不完全相关</strong>。如果两个模型结构相似、误差高度相关，组合的收益很小。</p><h2 id="_8-9-两种预测协议的对比" tabindex="-1">8.9 两种预测协议的对比 <a class="header-anchor" href="#_8-9-两种预测协议的对比" aria-label="Permalink to &quot;8.9 两种预测协议的对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>滚动一步</th><th>固定原点多步</th></tr></thead><tbody><tr><td>参数</td><td>每个原点重新估计</td><td>只在起点估计一次</td></tr><tr><td>信息集</td><td>每期更新</td><td>固定</td></tr><tr><td>预测步长</td><td>恒为 1</td><td>1 到 h</td></tr><tr><td>误差结构</td><td>只有一步误差</td><td>误差随 h 累积</td></tr><tr><td>模拟的现实场景</td><td>持续监控、每月更新</td><td>一次性规划、中途不调整</td></tr><tr><td>典型用途</td><td>评估模型的&quot;更新能力&quot;</td><td>评估模型的&quot;外推能力&quot;</td></tr></tbody></table><p>★ 一个常见的误判：看到滚动一步的 RMSE 很小，就认为模型&quot;预测很准&quot;。但滚动一步只预测下一个月，而实际业务往往需要预测一整年。两种协议的结论可能完全相反——<strong>滚动一步略优、固定原点明显劣于基准</strong>，是完全可能的，且这个组合本身很有信息量。</p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ol><li>最优预测是条件期望；预测误差均值为零，方差为 σ²Σψⱼ²。</li><li>AR 多步预测用预测值递归代入；MA 超过 q 步即回到均值。</li><li>平稳模型的区间宽度收敛到常数；含单位根的按 √h 增长。</li><li>含漂移 ARIMA 的长期预测是一条直线，斜率由漂移项决定。</li><li>组合预测的等权平均常优于估计权重，前提是误差不完全相关。</li><li>滚动一步与固定原点测的是两种能力，结论可以相反。</li></ol><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：最优预测是什么？h 步预测误差的方差怎么算？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>均方误差意义下的最优预测是<strong>条件期望</strong>。预测误差均值为零，方差为 <strong>σ²Σψⱼ²</strong>（j 从 0 到 h−1，ψⱼ 是 Green 函数权重）。</p></details><p><strong>Q2：平稳模型和含单位根模型的预测区间，随预测步长怎么变化？</strong></p><details class="details custom-block"><summary>点开看答案</summary><ul><li><strong>平稳模型</strong>：区间宽度随 h 增大，最后<strong>收敛到一个常数</strong>；</li><li><strong>含单位根</strong>：区间宽度按 <strong>√h 增长</strong>，不收敛。</li></ul><p>含漂移的 ARIMA，长期点预测是一条直线，斜率由漂移项决定。</p></details><p><strong>Q3：AR 和 MA 的多步预测有什么不同？</strong></p><details class="details custom-block"><summary>点开看答案</summary><ul><li><strong>AR</strong>：多步预测用前面的<strong>预测值递归代入</strong>；</li><li><strong>MA(q)</strong>：超过 q 步后，预测<strong>回到均值</strong>（再往后已经没有可用的冲击信息）。</li></ul></details>',40)])])}const q=s(n,[["render",d]]);export{c as __pageData,q as default};
